#!/usr/bin/env python3
"""Render the canonical offline business-flow and code-design workbench."""

import argparse
import html
import json
from pathlib import Path


def esc(value):
    return html.escape(str(value or ""), quote=True)


def validate_report(data):
    flow = data.get("flow_map")
    design = data.get("architecture_design")
    if not isinstance(flow, dict) or not flow.get("id"):
        raise ValueError("report.flow_map with an id is required")
    if not isinstance(design, dict):
        raise ValueError("report.architecture_design is required")

    code_map = data.get("code_map") or data
    source_ids = {
        node.get("id")
        for node in code_map.get("nodes", [])
        if isinstance(node, dict) and node.get("id")
    }
    lanes = {lane.get("id"): lane for lane in design.get("lanes", []) if lane.get("id")}
    contracts = {
        contract.get("id"): contract
        for contract in design.get("contracts", [])
        if contract.get("id")
    }
    if not lanes:
        raise ValueError("architecture_design.lanes must not be empty")
    for contract_id, contract in contracts.items():
        if contract.get("source_lane_id") not in lanes or contract.get("target_lane_id") not in lanes:
            raise ValueError(f"contract {contract_id} references a missing lane")
        for source_id in contract.get("source_node_ids") or []:
            if source_id not in source_ids:
                raise ValueError(f"contract {contract_id} references missing source {source_id}")

    flow_nodes = {}

    def visit(node):
        node_id = node.get("id")
        if not node_id:
            raise ValueError("every flow_map node requires an id")
        if node_id in flow_nodes:
            raise ValueError(f"duplicate flow_map node id: {node_id}")
        if node.get("lane_id") not in lanes:
            raise ValueError(f"flow node {node_id} references a missing lane")
        flow_nodes[node_id] = node
        for contract_id in (node.get("contract_in_ids") or []) + (node.get("contract_out_ids") or []):
            if contract_id not in contracts:
                raise ValueError(f"flow node {node_id} references missing contract {contract_id}")
        for source_id in node.get("source_node_ids") or []:
            if source_id not in source_ids:
                raise ValueError(f"flow node {node_id} references missing source {source_id}")
        for child in node.get("children") or []:
            visit(child)

    visit(flow)
    for node_id, node in flow_nodes.items():
        for branch in node.get("branches") or []:
            if branch.get("target_id") not in flow_nodes:
                raise ValueError(f"flow branch {node_id} targets missing node {branch.get('target_id')}")


